526		ID    string                `json:"id"`
527		Date  string                `json:"date"`
528		Memo  string                `json:"memo"`
529		Lines []*journalLineRequest `json:"lines"`
530	}
531	
532	// CreateJournal posts an immutable voucher once it balances in the functional
533	// currency. A date inside a closed period is rejected.
534	func (s *Service) CreateJournal(body []byte, key string) (any, error) {
535		var request createJournalRequest
536		if err := decodeObject(body, &request); err != nil {
537			return nil, err
538		}
539		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
540		if err != nil {
541			return nil, err
542		}
543		return s.runIdempotent(key, "create-journal:"+id, func(state *State) (any, error) {
544			if _, found := state.Journals[id]; found {
545				return nil, ConflictError("journal %s already exists", id)
546			}
547			if closedPeriodFor(state, date) != nil {
548				return nil, ConflictError("closed period rejects journal")
549			}
550			journal, err := s.buildJournal(state, &request, id, date, memo)
551			if err != nil {
552				return nil, err
553			}
554			state.Journals[id] = journal
555			return journal, nil
556		})
557	}
558	
559	// validateJournalHead checks the journal fields that do not depend on the
560	// stored state and returns them normalized.
561	func validateJournalHead(rawID, rawDate, rawMemo string, lineCount int) (string, string, string, error) {
562		id, err := validateIdentifier(rawID, "journal id")
563		if err != nil {
564			return "", "", "", err
565		}
566		date, err := validateDate(rawDate, "date")
567		if err != nil {
568			return "", "", "", err
569		}
570		memo, err := validateText(rawMemo, "memo")
571		if err != nil {
572			return "", "", "", err
573		}
574		if lineCount < 2 {
575			return "", "", "", ValidationError("lines must contain at least two postings")
576		}
577		return id, date, memo, nil
578	}
579	
580	// buildJournal resolves every line and freezes the balanced voucher. The
581	// caller owns the duplicate-id and closed-period policy.
582	func (s *Service) buildJournal(state *State, request *createJournalRequest, id, date, memo string) (*Journal, error) {
583		journal := &Journal{
584			ID:                 id,
585			Date:               date,
586			Memo:               memo,
587			FunctionalCurrency: s.functionalCurrency,
588			Lines:              []*JournalLine{},
589			CreatedAt:          s.now(),
590		}
591		var debits, credits int64
592		for position, raw := range request.Lines {
593			line, err := s.buildJournalLine(state, raw, position+1, date)
594			if err != nil {
595				return nil, err
596			}
597			if line.Side == "debit" {
598				debits += line.FunctionalAmountMinor
599			} else {
600				credits += line.FunctionalAmountMinor
601			}
602			journal.Lines = append(journal.Lines, line)
603		}
604		if debits != credits {
605			return nil, ValidationError(
606				"journal is not balanced in %s: debits %d, credits %d",
607				s.functionalCurrency, debits, credits,
608			)
609		}
610		journal.DebitFunctionalMinor = debits
611		journal.CreditFunctionalMinor = credits
612		return journal, nil
613	}
