615	// closedPeriodFor returns the close that covers date, or nil when the date
616	// falls in an open period.
617	func closedPeriodFor(state *State, date string) *PeriodClose {
618		for _, close := range state.PeriodCloses {
619			if close.Period.Start <= date && date <= close.Period.End {
620				return close
621			}
622		}
623		return nil
624	}
