637	type createReversalRequest struct {
638		ID   string `json:"id"`
639		Date string `json:"date"`
640		Memo string `json:"memo"`
641	}
642	
643	// CreateReversal posts exactly one reversal journal for the journal named in
644	// the path. The reversal mirrors every line of the original with debit and
645	// credit swapped, keeps the stored amounts, rate fractions, rate sources and
646	// functional amounts, and never resolves a fresh rate, so the pair cancels
647	// exactly in both the original and the functional currency. The reversal
648	// journal itself is the durable record that the original has been reversed:
649	// both are committed in the same atomic state write, so a restart cannot
650	// allow a second reversal.
651	func (s *Service) CreateReversal(journalID string, body []byte, key string) (any, error) {
652		var request createReversalRequest
653		if err := decodeObject(body, &request); err != nil {
654			return nil, err
655		}
656		id, err := validateIdentifier(request.ID, "journal id")
657		if err != nil {
658			return nil, err
659		}
660		date, err := validateDate(request.Date, "date")
661		if err != nil {
662			return nil, err
663		}
664		memo, err := validateText(request.Memo, "memo")
665		if err != nil {
666			return nil, err
667		}
668		if memo == "" {
669			return nil, ValidationError("memo is required")
670		}
671		return s.runIdempotent(key, "create-reversal:"+journalID+":"+id, func(state *State) (any, error) {
672			original, found := state.Journals[journalID]
673			if !found {
674				return nil, NotFoundError("journal %s was not found", journalID)
675			}
676			if date < original.Date {
677				return nil, ValidationError(
678					"date must not be earlier than the date %s of journal %s",
679					original.Date, journalID,
680				)
681			}
682			if original.ReversalOf != "" {
683				return nil, ConflictError("journal %s is itself a reversal and cannot be reversed", journalID)
684			}
685			for _, journal := range state.Journals {
686				if journal.ReversalOf == journalID {
687					return nil, ConflictError("journal %s was already reversed by %s", journalID, journal.ID)
688				}
689			}
690			if _, found := state.Journals[id]; found {
691				return nil, ConflictError("journal %s already exists", id)
692			}
693			if closedPeriodFor(state, date) != nil {
694				return nil, ConflictError("closed period rejects journal")
695			}
696			reversal := &Journal{
697				ID:                    id,
698				Date:                  date,
699				Memo:                  memo,
700				FunctionalCurrency:    original.FunctionalCurrency,
701				Lines:                 make([]*JournalLine, 0, len(original.Lines)),
702				DebitFunctionalMinor:  original.CreditFunctionalMinor,
703				CreditFunctionalMinor: original.DebitFunctionalMinor,
704				CreatedAt:             s.now(),
705				ReversalOf:            journalID,
706			}
707			for _, line := range original.Lines {
708				side := "debit"
709				if line.Side == "debit" {
710					side = "credit"
711				}
712				reversal.Lines = append(reversal.Lines, &JournalLine{
713					Index:                 line.Index,
714					AccountID:             line.AccountID,
715					Side:                  side,
716					AmountMinor:           line.AmountMinor,
717					Currency:              line.Currency,
718					Rate:                  line.Rate,
719					RateNumerator:         line.RateNumerator,
720					RateDenominator:       line.RateDenominator,
721					RateSource:            line.RateSource,
722					FunctionalAmountMinor: line.FunctionalAmountMinor,
723					Reference:             line.Reference,
724				})
725			}
726			state.Journals[id] = reversal
727			return reversal, nil
728		})
729	}
