731	type createPeriodCloseRequest struct {
732		ID     string        `json:"id"`
733		Period periodRequest `json:"period"`
734	}
735	
736	// CreatePeriodClose freezes one calendar month. The period must be exactly one
737	// natural month and no other close may cover the same month.
738	func (s *Service) CreatePeriodClose(body []byte, key string) (any, error) {
739		var request createPeriodCloseRequest
740		if err := decodeObject(body, &request); err != nil {
741			return nil, err
742		}
743		if _, err := validateIdentifier(request.ID, "period close id"); err != nil {
744			return nil, ValidationError("invalid period close id")
745		}
746		id := request.ID
747		start, err := validatePeriodCloseDate(request.Period.Start)
748		if err != nil {
749			return nil, err
750		}
751		end, err := validatePeriodCloseDate(request.Period.End)
752		if err != nil {
753			return nil, err
754		}
755		if !isCalendarMonth(start, end) {
756			return nil, ValidationError("period is not one calendar month")
757		}
758		return s.runIdempotent(key, "create-period-close:"+id, func(state *State) (any, error) {
759			if _, found := state.PeriodCloses[id]; found {
760				return nil, ConflictError("period close exists")
761			}
762			for _, existing := range state.PeriodCloses {
763				if existing.Period.Start[:7] == start[:7] {
764					return nil, ConflictError("calendar month is closed")
765				}
766			}
767			close := &PeriodClose{
768				ID:                   id,
769				Period:               Period{Start: start, End: end},
770				Status:               "closed",
771				ClosedAt:             s.now(),
772				AdjustmentCount:      0,
773				AdjustmentJournalIDs: []string{},
774			}
775			state.PeriodCloses[id] = close
776			return close, nil
777		})
778	}
779	
780	// validatePeriodCloseDate applies the public YYYY-MM-DD rule under the period
781	// close message.
782	func validatePeriodCloseDate(value string) (string, error) {
783		if _, err := validateDate(value, "period date"); err != nil {
784			return "", ValidationError("invalid period date")
785		}
786		return value, nil
787	}
788	
789	// isCalendarMonth reports whether start and end together span exactly one
790	// natural month, first day to last day.
791	func isCalendarMonth(start, end string) bool {
792		first, err := time.Parse(dateLayout, start)
793		if err != nil || first.Day() != 1 {
794			return false
795		}
796		last, err := time.Parse(dateLayout, end)
797		if err != nil {
798			return false
799		}
800		return last.Equal(first.AddDate(0, 1, -1))
801	}
