804	func (s *Service) GetPeriodClose(id string) (any, error) {
805		return s.store.View(func(state *State) (any, error) {
806			close, found := state.PeriodCloses[id]
807			if !found {
808				return nil, NotFoundError("period close not found")
809			}
810			return close, nil
811		})
812	}
