814	// CreateAdjustment posts an adjustment journal into a closed period through
815	// its close. The voucher follows every ordinary journal rule and additionally
816	// requires a memo and a date inside the closed period.
817	func (s *Service) CreateAdjustment(closeID string, body []byte, key string) (any, error) {
818		var request createJournalRequest
819		if err := decodeObject(body, &request); err != nil {
820			return nil, err
821		}
822		id, date, memo, err := validateJournalHead(request.ID, request.Date, request.Memo, len(request.Lines))
823		if err != nil {
824			return nil, err
825		}
826		return s.runIdempotent(key, "create-adjustment:"+closeID+":"+id, func(state *State) (any, error) {
827			close, found := state.PeriodCloses[closeID]
828			if !found {
829				return nil, NotFoundError("period close not found")
830			}
831			if memo == "" {
832				return nil, ValidationError("adjustment memo required")
833			}
834			if date < close.Period.Start || date > close.Period.End {
835				return nil, ValidationError("adjustment date outside period")
836			}
837			if _, found := state.Journals[id]; found {
838				return nil, ConflictError("journal exists")
839			}
840			journal, err := s.buildJournal(state, &request, id, date, memo)
841			if err != nil {
842				return nil, err
843			}
844			state.Journals[id] = journal
845			close.AdjustmentJournalIDs = append(close.AdjustmentJournalIDs, id)
846			close.AdjustmentCount = len(close.AdjustmentJournalIDs)
847			return journal, nil
848		})
849	}
