851	func (s *Service) buildJournalLine(state *State, raw *journalLineRequest, index int, date string) (*JournalLine, error) {
852		if raw == nil {
853			return nil, ValidationError("lines[%d] must be an object", index)
854		}
855		accountID, err := validateIdentifier(raw.AccountID, fmt.Sprintf("lines[%d].account_id", index))
856		if err != nil {
857			return nil, err
858		}
859		account, found := state.Accounts[accountID]
860		if !found {
861			return nil, ValidationError("lines[%d].account_id %s does not exist", index, accountID)
862		}
863		if raw.Side != "debit" && raw.Side != "credit" {
864			return nil, ValidationError("lines[%d].side must be debit or credit", index)
865		}
866		amount, err := validateAmount(raw.AmountMinor, fmt.Sprintf("lines[%d].amount_minor", index), false, false)
867		if err != nil {
868			return nil, err
869		}
870		currency, err := validateCurrency(raw.Currency, fmt.Sprintf("lines[%d].currency", index), false)
871		if err != nil {
872			return nil, err
873		}
874		if currency == "" {
875			currency = account.Currency
876		}
877		if currency != account.Currency {
878			return nil, ValidationError(
879				"lines[%d].currency %s must match the currency %s of account %s",
880				index, currency, account.Currency, accountID,
881			)
882		}
883		reference, err := validateText(raw.Reference, fmt.Sprintf("lines[%d].reference", index))
884		if err != nil {
885			return nil, err
886		}
887		numerator, denominator, source, err := s.resolveRate(state, currency, date, raw.Rate, fmt.Sprintf("lines[%d].rate", index))
888		if err != nil {
889			return nil, err
890		}
891		functional, err := convertMinor(amount, numerator, denominator)
892		if err != nil {
893			return nil, err
894		}
895		if functional < 1 {
896			return nil, ValidationError(
897				"lines[%d] converts to zero minor units in %s; use a larger amount or a finer exchange rate",
898				index, s.functionalCurrency,
899			)
900		}
901		return &JournalLine{
902			Index:                 index,
903			AccountID:             accountID,
904			Side:                  raw.Side,
905			AmountMinor:           amount,
906			Currency:              currency,
907			Rate:                  raw.Rate,
908			RateNumerator:         numerator,
909			RateDenominator:       denominator,
910			RateSource:            source,
911			FunctionalAmountMinor: functional,
912			Reference:             reference,
913		}, nil
914	}
