916	// resolveRate returns the exact fraction that converts one minor unit of
917	// currency into the functional currency for the given date.
918	func (s *Service) resolveRate(state *State, currency, date, declared, field string) (int64, int64, string, error) {
919		if currency == s.functionalCurrency {
920			if declared == "" || declared == "1" {
921				return 1, 1, "identity", nil
922			}
923			numerator, denominator, err := parseRateFraction(declared, field)
924			if err != nil {
925				return 0, 0, "", err
926			}
927			if numerator != denominator {
928				return 0, 0, "", ValidationError(
929					"%s must be omitted or exactly 1 because %s is the functional currency",
930					field, currency,
931				)
932			}
933			return 1, 1, "identity", nil
934		}
935		if declared != "" {
936			numerator, denominator, err := parseRateFraction(declared, field)
937			if err != nil {
938				return 0, 0, "", err
939			}
940			return numerator, denominator, "declared", nil
941		}
942		if direct := latestRate(state, currency, s.functionalCurrency, date); direct != nil {
943			return direct.Numerator, direct.Denominator, "snapshot:" + direct.Date, nil
944		}
945		if inverse := latestRate(state, s.functionalCurrency, currency, date); inverse != nil {
946			return inverse.Denominator, inverse.Numerator, "snapshot-inverse:" + inverse.Date, nil
947		}
948		return 0, 0, "", ValidationError(
949			"no %s/%s exchange rate snapshot exists on or before %s",
950			currency, s.functionalCurrency, date,
951		)
952	}
