978	func (s *Service) CreateStatement(body []byte, key string) (any, error) {
979		var request createStatementRequest
980		if err := decodeObject(body, &request); err != nil {
981			return nil, err
982		}
983		id, err := validateIdentifier(request.ID, "statement id")
984		if err != nil {
985			return nil, err
986		}
987		accountID, err := validateIdentifier(request.AccountID, "account_id")
988		if err != nil {
989			return nil, err
990		}
991		currency, err := validateCurrency(request.Currency, "currency", false)
992		if err != nil {
993			return nil, err
994		}
995		start, err := validateDate(request.Period.Start, "period.start")
996		if err != nil {
997			return nil, err
998		}
999		end, err := validateDate(request.Period.End, "period.end")
1000		if err != nil {
1001			return nil, err
1002		}
1003		if start > end {
1004			return nil, ValidationError("period.start must not be after period.end")
1005		}
1006		opening, err := validateAmount(request.OpeningBalanceMinor, "opening_balance_minor", true, true)
1007		if err != nil {
1008			return nil, err
1009		}
1010		closing, err := validateAmount(request.ClosingBalanceMinor, "closing_balance_minor", true, true)
1011		if err != nil {
1012			return nil, err
1013		}
1014		return s.runIdempotent(key, "create-statement:"+id, func(state *State) (any, error) {
1015			if _, found := state.Statements[id]; found {
1016				return nil, ConflictError("statement %s already exists", id)
1017			}
1018			account, found := state.Accounts[accountID]
1019			if !found {
1020				return nil, ValidationError("account_id %s does not exist", accountID)
1021			}
1022			if currency == "" {
1023				currency = account.Currency
1024			}
1025			if currency != account.Currency {
1026				return nil, ValidationError(
1027					"currency %s must match the currency %s of account %s",
1028					currency, account.Currency, accountID,
1029				)
1030			}
1031			statement := &Statement{
1032				ID:                  id,
1033				AccountID:           accountID,
1034				Currency:            currency,
1035				Period:              Period{Start: start, End: end},
1036				OpeningBalanceMinor: opening,
1037				ClosingBalanceMinor: closing,
1038				Lines:               []*StatementLine{},
1039				CreatedAt:           s.now(),
1040			}
1041			total := opening
1042			seen := map[string]bool{}
1043			for position, raw := range request.Lines {
1044				if raw == nil {
1045					return nil, ValidationError("lines[%d] must be an object", position+1)
1046				}
1047				field := fmt.Sprintf("lines[%d]", position+1)
1048				lineID, err := validateIdentifier(raw.ID, field+".id")
1049				if err != nil {
1050					return nil, err
1051				}
1052				if seen[lineID] {
1053					return nil, ValidationError("statement line id %s is duplicated", lineID)
1054				}
1055				seen[lineID] = true
1056				lineDate, err := validateDate(raw.Date, field+".date")
1057				if err != nil {
1058					return nil, err
1059				}
1060				if lineDate < start || lineDate > end {
1061					return nil, ValidationError("%s.date must fall inside the statement period", field)
1062				}
1063				amount, err := validateAmount(raw.AmountMinor, field+".amount_minor", false, true)
1064				if err != nil {
1065					return nil, err
1066				}
1067				reference, err := validateText(raw.Reference, field+".reference")
1068				if err != nil {
1069					return nil, err
1070				}
1071				description, err := validateText(raw.Description, field+".description")
1072				if err != nil {
1073					return nil, err
1074				}
1075				total += amount
1076				statement.Lines = append(statement.Lines, &StatementLine{
1077					ID:          lineID,
1078					Date:        lineDate,
1079					AmountMinor: amount,
1080					Reference:   reference,
1081					Description: description,
1082				})
1083			}
1084			if total != closing {
1085				return nil, ValidationError(
1086					"statement lines do not reconcile with the closing balance: opening %d plus lines %d is %d, not %d",
1087					opening, total-opening, total, closing,
1088				)
1089			}
1090			state.Statements[id] = statement
1091			return statement, nil
1092		})
1093	}
