1154	// ledgerEntry is one journal line seen from the ledger side of a
1155	// reconciliation. AmountMinor is signed with debits positive.
1156	type ledgerEntry struct {
1157		ID          string
1158		Date        string
1159		AmountMinor int64
1160		Reference   string
1161	}
1162	
1163	func ledgerEntries(state *State, accountID string, period Period) []*ledgerEntry {
1164		entries := []*ledgerEntry{}
1165		for _, journal := range sortedJournals(state) {
1166			if journal.Date < period.Start || journal.Date > period.End {
1167				continue
1168			}
1169			for _, line := range journal.Lines {
1170				if line.AccountID != accountID {
1171					continue
1172				}
1173				amount := line.AmountMinor
1174				if line.Side == "credit" {
1175					amount = -amount
1176				}
1177				entries = append(entries, &ledgerEntry{
1178					ID:          fmt.Sprintf("%s#%d", journal.ID, line.Index),
1179					Date:        journal.Date,
1180					AmountMinor: amount,
1181					Reference:   line.Reference,
1182				})
1183			}
1184		}
1185		return entries
1186	}
1187	
1188	var differenceOrder = map[string]int{
1189		"timing":               0,
1190		"amount_mismatch":      1,
1191		"missing_in_ledger":    2,
1192		"missing_in_statement": 3,
1193	}
1194	
1195	// computeReconciliation matches statement lines to ledger lines in three
1196	// deterministic tiers and classifies everything that stays unmatched.
1197	func (s *Service) computeReconciliation(state *State, statement *Statement, id, createdAt string) (*Reconciliation, error) {
1198		lines := make([]*StatementLine, 0, len(statement.Lines))
1199		lines = append(lines, statement.Lines...)
1200		sort.Slice(lines, func(left, right int) bool { return lines[left].ID < lines[right].ID })
1201	
1202		entries := ledgerEntries(state, statement.AccountID, statement.Period)
1203		sort.Slice(entries, func(left, right int) bool { return entries[left].ID < entries[right].ID })
1204	
1205		statementUsed := make([]bool, len(lines))
1206		ledgerUsed := make([]bool, len(entries))
1207		differences := []*Difference{}
1208		matched := 0
1209		match := func(statementIndex, ledgerIndex int, difference *Difference) {
1210			statementUsed[statementIndex] = true
1211			ledgerUsed[ledgerIndex] = true
1212			matched++
1213			if difference != nil {
1214				differences = append(differences, difference)
1215			}
1216		}
1217	
1218		// Tier 1: same signed amount and same date.
1219		for index, line := range lines {
1220			for other, entry := range entries {
1221				if ledgerUsed[other] {
1222					continue
1223				}
1224				if entry.AmountMinor == line.AmountMinor && entry.Date == line.Date {
1225					match(index, other, nil)
1226					break
1227				}
1228			}
1229		}
1230	
1231		// Tier 2: same signed amount, different date, so it only differs in timing.
1232		for index, line := range lines {
1233			if statementUsed[index] {
1234				continue
1235			}
1236			for other, entry := range entries {
1237				if ledgerUsed[other] || entry.AmountMinor != line.AmountMinor {
1238					continue
1239				}
1240				statementAmount := line.AmountMinor
1241				ledgerAmount := entry.AmountMinor
1242				match(index, other, &Difference{
1243					Type:                 "timing",
1244					Detail:               "the amounts agree but the ledger date differs from the statement date",
1245					StatementLineID:      line.ID,
1246					LedgerLineID:         entry.ID,
1247					StatementDate:        line.Date,
1248					LedgerDate:           entry.Date,
1249					StatementAmountMinor: &statementAmount,
1250					LedgerAmountMinor:    &ledgerAmount,
1251				})
1252				break
1253			}
1254		}
1255	
1256		// Tier 3: same non-empty reference but a different amount.
1257		for index, line := range lines {
1258			if statementUsed[index] || line.Reference == "" {
1259				continue
1260			}
1261			for other, entry := range entries {
1262				if ledgerUsed[other] || entry.Reference == "" || entry.Reference != line.Reference {
1263					continue
1264				}
1265				statementAmount := line.AmountMinor
1266				ledgerAmount := entry.AmountMinor
1267				match(index, other, &Difference{
1268					Type:                 "amount_mismatch",
1269					Detail:               fmt.Sprintf("reference %s appears on both sides with different amounts", line.Reference),
1270					StatementLineID:      line.ID,
1271					LedgerLineID:         entry.ID,
1272					StatementDate:        line.Date,
1273					LedgerDate:           entry.Date,
1274					StatementAmountMinor: &statementAmount,
1275					LedgerAmountMinor:    &ledgerAmount,
1276					DifferenceMinor:      statementAmount - ledgerAmount,
1277				})
1278				break
1279			}
1280		}
1281	
1282		// Everything still unmatched is missing on one side.
1283		for index, line := range lines {
1284			if statementUsed[index] {
1285				continue
1286			}
1287			amount := line.AmountMinor
1288			differences = append(differences, &Difference{
1289				Type:                 "missing_in_ledger",
1290				Detail:               "the statement line has no journal line in the period",
1291				StatementLineID:      line.ID,
1292				StatementDate:        line.Date,
1293				StatementAmountMinor: &amount,
1294				DifferenceMinor:      amount,
1295			})
1296		}
1297		for index, entry := range entries {
1298			if ledgerUsed[index] {
1299				continue
1300			}
1301			amount := entry.AmountMinor
1302			differences = append(differences, &Difference{
1303				Type:              "missing_in_statement",
1304				Detail:            "the journal line has no statement line in the period",
1305				LedgerLineID:      entry.ID,
1306				LedgerDate:        entry.Date,
1307				LedgerAmountMinor: &amount,
1308				DifferenceMinor:   -amount,
1309			})
1310		}
1311	
1312		sort.SliceStable(differences, func(left, right int) bool {
1313			a, b := differences[left], differences[right]
1314			if differenceOrder[a.Type] != differenceOrder[b.Type] {
1315				return differenceOrder[a.Type] < differenceOrder[b.Type]
1316			}
1317			if a.StatementLineID != b.StatementLineID {
1318				return a.StatementLineID < b.StatementLineID
1319			}
1320			return a.LedgerLineID < b.LedgerLineID
1321		})
1322	
1323		var ledgerNet int64
1324		for _, entry := range entries {
1325			ledgerNet += entry.AmountMinor
1326		}
1327		statementNet := statement.ClosingBalanceMinor - statement.OpeningBalanceMinor
1328	
1329		summary := DifferenceSummary{}
1330		var explained int64
1331		for _, difference := range differences {
1332			explained += difference.DifferenceMinor
1333			switch difference.Type {
1334			case "timing":
1335				summary.Timing++
1336			case "amount_mismatch":
1337				summary.AmountMismatch++
1338			case "missing_in_ledger":
1339				summary.MissingInLedger++
1340			case "missing_in_statement":
1341				summary.MissingInStatement++
1342			default:
1343				return nil, InternalError("reconciliation produced the unknown difference type %s", difference.Type)
1344			}
1345		}
1346		if 2*matched+summary.MissingInLedger+summary.MissingInStatement != len(lines)+len(entries) {
1347			return nil, InternalError("reconciliation differences are not mutually exclusive and complete")
1348		}
1349		if explained != statementNet-ledgerNet {
1350			return nil, InternalError("reconciliation differences do not add up to the period difference")
1351		}
1352	
1353		status := "balanced"
1354		if len(differences) > 0 {
1355			status = "differences_found"
1356		}
1357		return &Reconciliation{
1358			ID:                 id,
1359			StatementID:        statement.ID,
1360			AccountID:          statement.AccountID,
1361			Currency:           statement.Currency,
1362			FunctionalCurrency: s.functionalCurrency,
1363			Period:             statement.Period,
1364			Status:             status,
1365			MatchedCount:       matched,
1366			StatementLineCount: len(lines),
1367			LedgerLineCount:    len(entries),
1368			StatementNetMinor:  statementNet,
1369			LedgerNetMinor:     ledgerNet,
1370			DifferenceMinor:    statementNet - ledgerNet,
1371			Summary:            summary,
1372			Differences:        differences,
1373			CreatedAt:          createdAt,
1374		}, nil
1375	}
1376	
1377	func sortedAccounts(state *State) []*Account {
1378		accounts := make([]*Account, 0, len(state.Accounts))
1379		for _, account := range state.Accounts {
1380			accounts = append(accounts, account)
1381		}
1382		sort.Slice(accounts, func(left, right int) bool { return accounts[left].ID < accounts[right].ID })
1383		return accounts
1384	}
1385	
1386	func sortedJournals(state *State) []*Journal {
1387		journals := make([]*Journal, 0, len(state.Journals))
1388		for _, journal := range state.Journals {
1389			journals = append(journals, journal)
1390		}
1391		sort.Slice(journals, func(left, right int) bool {
1392			if journals[left].Date != journals[right].Date {
1393				return journals[left].Date < journals[right].Date
1394			}
1395			return journals[left].ID < journals[right].ID
1396		})
1397		return journals
1398	}
1399	
1400	func sortedRates(state *State) []*Rate {
1401		rates := make([]*Rate, 0, len(state.Rates))
1402		rates = append(rates, state.Rates...)
1403		sort.Slice(rates, func(left, right int) bool {
1404			a, b := rates[left], rates[right]
1405			if a.Base != b.Base {
1406				return a.Base < b.Base
1407			}
1408			if a.Quote != b.Quote {
1409				return a.Quote < b.Quote
1410			}
1411			return a.Date < b.Date
1412		})
1413		return rates
1414	}
1415	
1416	func accountTree(state *State) (map[string]*AccountNode, []*AccountNode) {
1417		nodes := map[string]*AccountNode{}
1418		for _, account := range state.Accounts {
1419			nodes[account.ID] = &AccountNode{Account: *account, Children: []*AccountNode{}}
1420		}
1421		roots := []*AccountNode{}
1422		for _, account := range sortedAccounts(state) {
1423			node := nodes[account.ID]
1424			if account.ParentID == nil {
1425				roots = append(roots, node)
1426				continue
1427			}
1428			parent, found := nodes[*account.ParentID]
1429			if !found {
1430				roots = append(roots, node)
1431				continue
1432			}
1433			parent.Children = append(parent.Children, node)
1434		}
1435		return nodes, roots
1436	}
1437	
1438	// latestRate returns the most recent snapshot for one direction that is
1439	// effective on the given date.
1440	func latestRate(state *State, base, quote, asOf string) *Rate {
1441		var best *Rate
1442		for _, rate := range state.Rates {
1443			if rate.Base != base || rate.Quote != quote || rate.Date > asOf {
1444				continue
1445			}
1446			if best == nil || rate.Date > best.Date {
1447				best = rate
1448			}
1449		}
1450		return best
1451	}
1452

