184	func readJSONBody(request *http.Request) ([]byte, error) {
185		contentType := request.Header.Get("Content-Type")
186		mediaType, _, _ := strings.Cut(contentType, ";")
187		if strings.TrimSpace(strings.ToLower(mediaType)) != "application/json" {
188			return nil, ValidationError("Content-Type must be application/json")
189		}
190		body, err := io.ReadAll(io.LimitReader(request.Body, maxBodyBytes+1))
191		if err != nil {
192			return nil, ValidationError("request body could not be read")
193		}
194		if len(body) > maxBodyBytes {
195			return nil, ValidationError("request body must be at most %d bytes", maxBodyBytes)
196		}
197		return body, nil
198	}
199	
200	func splitPath(path string) []string {
201		parts := []string{}
202		for _, part := range strings.Split(path, "/") {
203			if part != "" {
204				parts = append(parts, part)
205			}
206		}
207		return parts
208	}
209	
210	// requireQuery rejects every query parameter that the route does not document.
211	func requireQuery(request *http.Request, allowed ...string) error {
212		names := make([]string, 0, len(request.URL.Query()))
213		for name := range request.URL.Query() {
214			names = append(names, name)
215		}
216		sort.Strings(names)
217		for _, name := range names {
218			known := false
219			for _, candidate := range allowed {
220				if name == candidate {
221					known = true
222					break
223				}
224			}
225			if !known {
226				return ValidationError("unknown query parameter %s", name)
227			}
228		}
229		return nil
230	}
231	
232	// requireSingleQuery rejects unknown query parameters and repeated values for
233	// the single documented parameter, so its value can be trusted as a scalar.
234	func requireSingleQuery(request *http.Request, name string) error {
235		query := request.URL.Query()
236		if len(query[name]) > 1 {
237			return ValidationError("query parameter %s must appear exactly once", name)
238		}
239		for candidate := range query {
240			if candidate != name {
241				return ValidationError("unknown query parameter %s", candidate)
242			}
243		}
244		return nil
245	}
246	
247	// requireNamedQueries rejects unknown query parameters and repeated values for
248	// every documented name, checking the names in the order the route documents
249	// so the first failure is reported in that order.
250	func requireNamedQueries(request *http.Request, names ...string) error {
251		query := request.URL.Query()
252		for _, name := range names {
253			if len(query[name]) == 0 {
254				return ValidationError("%s query parameter is required", name)
255			}
256			if len(query[name]) > 1 {
257				return ValidationError("query parameter %s must appear exactly once", name)
258			}
259		}
260		for candidate := range query {
261			known := false
262			for _, name := range names {
263				if candidate == name {
264					known = true
265					break
266				}
267			}
268			if !known {
269				return ValidationError("unknown query parameter %s", candidate)
270			}
271		}
272		return nil
273	}
274	
275	func writeError(writer http.ResponseWriter, err error) {
276		apiError := &Error{Code: "internal_error", Status: 500, Message: "internal server error"}
277		var typed *Error
278		if errors.As(err, &typed) {
279			apiError = typed
280		}
281		writeJSON(writer, apiError.Status, map[string]any{
282			"error": map[string]any{"code": apiError.Code, "message": apiError.Message},
283		})
284	}
285	
286	func writeJSON(writer http.ResponseWriter, status int, value any) {
287		encoded, err := json.Marshal(value)
288		if err != nil {
289			status = http.StatusInternalServerError
290			encoded = []byte(`{"error":{"code":"internal_error","message":"internal server error"}}`)
291		}
292		writer.Header().Set("Content-Type", "application/json; charset=utf-8")
293		writer.Header().Set("Content-Length", strconv.Itoa(len(encoded)))
294		writer.WriteHeader(status)
295		writer.Write(encoded)
296	}
